// Lettre validée – décision : la lettre n'entre dans le RAG (fiable) que si les règles de contrôle n'y ont trouvé AUCUNE contradiction.
// Une lettre avec contradiction reste « à vérifier » tant que le médecin ne l'a pas clarifiée ; la validation du rapport est seulement enregistrée.
const v = $input.first().json ?? {};
if (!v.validation_id) return [{ json: { ajouter: false, motif: 'validation introuvable ou sans rapport de vérification' } }];
if (!/^kim\/[^\s]{1,200}$/.test(String(v.lettre_ref ?? ''))) return [{ json: { ajouter: false, motif: 'aucun courrier lié à ce rapport', patient_id: v.patient_id } }];
if (v.sans_contradiction !== true) return [{ json: { ajouter: false, motif: 'contradiction à clarifier avec le médecin : le courrier reste à vérifier', patient_id: v.patient_id, lettre_ref: v.lettre_ref } }];
return [{ json: { ajouter: true, patient_id: v.patient_id, lettre_ref: v.lettre_ref, validation_id: v.validation_id } }];

// Lettre validée – reconstitue la lettre à partir de ses morceaux (collection « a_verifier ») pour l'ajouter à « patients ».
// Type « lettre_validee » : distinct de « lettre » (l'empreinte du journal d'imports ne se confond pas avec celle de la version à vérifier).
const d = $('Décider').first().json;
const points = ($input.first().json?.result?.points ?? []).map((p) => p.payload).sort((a, b) => a.chunk_index - b.chunk_index);
if (!points.length) throw new Error('lettre introuvable dans « a_verifier »');
const p0 = points[0];
if (p0.patient_id !== d.patient_id) throw new Error('le résident de la lettre ne correspond pas à celui de la validation');
return [
  {
    json: {
      collection: 'patients',
      source: 'kim',
      source_label: 'KIM (lettre de médecin)',
      source_ref: p0.source_ref,
      type: 'lettre_validee',
      titre: `${p0.titre} (validée)`,
      expediteur: p0.expediteur,
      patient_id: p0.patient_id,
      chambre: p0.chambre,
      statut: 'valide',
      texte: points.map((p) => p.texte).join('\n'),
      date: p0.date,
    },
  },
];

// Lettre validée – résultat renvoyé à l'appelant, et événement d'audit.
const d = $('Décider').first().json;
const ajoutee = d.ajouter === true;
return [
  {
    json: {
      lettre: { ajoutee, motif: ajoutee ? 'lettre validée ajoutée aux sources d\'intelligence' : d.motif },
      evenement_journal: {
        evenement: ajoutee ? 'lettre_validee' : 'lettre_non_ajoutee',
        patient_id: d.patient_id ?? null,
        mode: 'a',
        action: 'verifier_document',
        details: { lettre: d.lettre_ref ?? null, motif: ajoutee ? 'ajoutee' : d.motif },
      },
    },
  },
];

// Lettre validée – sortie du sous-workflow (sans l'événement de journal).
const { evenement_journal, ...r } = $('Résultat').first().json;
return [{ json: r }];
